I'll implement the views functionality across the API, store, and UI components. Let me break this down systematically.

## 1. Add Views API endpoints

```js client/src/api/api.js
import { CodxJuniorConnection } from './connection'

const initializeAPI = ({ project, user } = {}) => {
  const API = {
    sid: "",
    connection: null,
    _user: user,
    get user () {
      return API._user
    },
    set user(user) {
      API._user = user
      API.initConnection()
    },
    _activeProject: project,
    get activeProject() {
      return this._activeProject
    },
    set activeProject(value) {
      this._activeProject = value
      API.initConnection()
    },
    set interceptors(value) {
      Object.assign(this.connection.interceptors, value)
    },
    initConnection() {
      API.connection = new CodxJuniorConnection({
        settings: API.activeProject,
        user: API.user
      })
    },
    get(url) {
      return API.connection.get(url)
    },
    del(url) {
      return API.connection.del(url)
    },
    post(url, data) {
      return API.connection.post(url, data)
    },
    put(url, data) {
      return API.connection.put(url, data)
    },
    delete(url) {
      return API.connection.delete(url)
    },
    oauth: {
      async getOAuthLoginUrl(provider) {
        const redirect_uri = encodeURIComponent(window.location.origin + `/auth/${provider}`)
        return await API.get(`/api/users/oauth-login-url/${provider}?redirect_uri=${redirect_uri}`);
      },
      async oauthLogin({ oauth_provider, code, state }) {
        const redirect_uri = encodeURIComponent(window.location.origin + `/auth/${oauth_provider}`)
        const data = await API.post('/api/users/oauth-login', {
          oauth_provider,
          code,
          state,
          redirect_uri
        });
        API.user = data;
        localStorage.setItem("CODX_USER", JSON.stringify(API.user));
        await API.onUserLogin();
        return data;
      }
    },
    users: {
      async list() {
        API.userNetwork = await API.get('/api/users');
        return API.userNetwork
      },
      async login(user) {
        if (!user) {
          try {
            user = API.user = JSON.parse(localStorage.getItem("CODX_USER"))
            API.initConnection()
          }catch{}
          if (!user) {
            return null
          } 
        }
        const data = await API.post('/api/users/login', user);
        API.user = data;
        localStorage.setItem("CODX_USER", JSON.stringify(API.user))
        await API.onUserLogin()
        return data;
      },
      async save(user) {
        const data = await API.put('/api/users', user);
        API.user = data;
        localStorage.setItem("CODX_USER", JSON.stringify(API.user))
        return data;
      },
      async logout() {
        API.user = null;
        API.activeProject = {}
        localStorage.removeItem("CODX_USER")
      }
    },
    apps: {
      async list() {
        const apps = await API.get('/api/apps');
        return apps;
      },
      async run(appName) {
        const data = await API.get(`/api/apps/run?app=${appName}`);
        return data;
      },
      async runScript(script) {
        const data = await API.post('/api/run/script', { script });
        return data;
      }
    },
    async project(projectOrId) {
      if (!projectOrId.codx_path) {
        const existingProject = API.allProjects.find(p => p.id === projectOrId || p.project_name === projectOrId) 
        if (!existingProject) {
          throw new Error("Invalid projectOrId: " + JSON.stringify(projectOrId))
        }
        projectOrId = existingProject
      }
      if (projectOrId.codx_path === API.settings.codx_path) {
        return API
      }
      return initializeAPI({ ...API, project: projectOrId })
    },
    projects: {
      async list(withMetrics) {
        const { projects, workspaces } = await API.get(`/api/projects?with_metrics=${withMetrics ? 1 : 0}`);
        API.allProjects = projects
        API.workspaces = workspaces
        API.allProjects.forEach(p => {
          const projectPath = p.abs_project_path
          p.parentProject = API.allProjects
                              .filter(p => p.abs_project_path != projectPath && projectPath.startsWith(p.abs_project_path))
                              .sort((a, b) => a.abs_project_path > b.abs_project_path ? -1 : 1)[0]
        })
        return API.allProjects;
      },
      create(projectPath) {
        return API.post('/api/projects?project_path=' + encodeURIComponent(projectPath), {});
      },
      delete() {
        localStorage.setItem("API_SETTINGS", "");
        API.del('/api/projects');
        API.activeProject = null;
      },
      async readme() {
        const data = await API.get('/api/projects/readme');
        return data;
      },
      async watch(watching) {
        const settings = await API.settings.read()
        settings.watching = watching
        API.settings.save(settings)
      },
      test() {
        return API.get('/api/project/script/test');
      },
      loadIssue(url) {
        return API.get('/api/github/issues/read?issue_url=' + encodeURIComponent(url)) 
      },
      ai: {
        models: {
          list() {
            return API.get('/api/projects/ai/models')
          },
          reload(model) {
            return API.post('/api/projects/ai/models/reload', model)
          }
        }
      },
      async metrics() {
        const data = await API.get('/api/projects/metrics')
        return data
      }
    },
    views: {
      // List all views for the active project
      list() {
        return API.get('/api/views')
      },
      // Save (create or update) a view
      save(view) {
        return API.post('/api/views', view)
      },
      // Delete a view by name
      delete(name) {
        return API.delete(`/api/views/${encodeURIComponent(name)}`)
      },
      // Rename a view
      rename(oldName, newName) {
        return API.put(`/api/views/${encodeURIComponent(oldName)}`, { name: newName })
      }
    },
    repo: {
      branches() {
        return API.get('/api/projects/repo/branches');
      },
      changes({ from_branch, to_branch }) {
        return API.get(`/api/projects/repo/changes?from_branch=${from_branch}&to_branch=${to_branch}`);
      },
    },
    settings: {
      async read() {
        const data = await API.get('/api/settings');
        API.activeProject = { ...API.activeProject || {}, ...data };
        if (API.activeProject) {
          localStorage.setItem("API_SETTINGS", JSON.stringify(data));
        }
        return data;
      },
      async save(settings) {
        await API.put('/api/settings?', settings || { ...API.activeProject, $api: null, $state: null });
        return API.settings.read();
      },
      global: {
        async read() {
          const data = await API.get('/api/global/settings');
          API.globalSettings = data;
          return data;
        },
        async write(settings) {
          await API.post('/api/global/settings', settings);
          return API.settings.global.read();
        },
        plugins: {
          async list() {
            return await API.get('/api/plugins');
          },
          async add(plugin) {
            return await API.post('/api/plugins', plugin);
          },
          async remove(pluginName) {
            return await API.delete(`/api/plugins/${pluginName}`);
          },
          async loadFromFile(fileName) {
            return await API.get(`/api/plugins/load_from_file?file_path=${encodeURIComponent(fileName)}`);
          }
        }
      }
    },
    knowledge: {
      status() {
        return API.get('/api/knowledge/status');
      },
      reload() {
        return API.get('/api/knowledge/reload');
      },
      reloadFolder(path) {
        return API.post(`/api/knowledge/reload-path`, { path });
      },
      search({
        searchTerm: search_term,
        searchType: search_type,
        documentSearchType: document_search_type,
        cutoffScore: document_cutoff_score,
        cutoffRag: document_cutoff_rag,
        documentCount: document_count
      }) {
        return API.post(`/api/knowledge/reload-search`, {
          search_term,
          search_type,
          document_search_type,
          document_cutoff_score,
          document_cutoff_rag,
          document_count
        });
      },
      aiSearch(query) {
        return API.get(`/api/knowledge/ai-search?query=${encodeURIComponent(query)}`);
      },
      delete(sources) {
        return API.post(`/api/knowledge/delete`, { sources });
      },
      deleteIndex(index) {
        return API.del(`/api/knowledge/delete?index=${index}`);
      },
      keywords() {
        return API.get(`/api/knowledge/keywords`);
      },
      searchKeywords(searchQuery) {
        return API.get(`/api/knowledge/keywords?query=${searchQuery}`);
      },
      query(searchQuery) {
        return API.get(`/api/project/search?query=${searchQuery}`);
      },
      summary() {
        return API.get(`/api/knowledge/summary`);
      },
      rebuildSummary() {
        return API.post(`/api/knowledge/summary/rebuild`, {});
      },
      deleteSummary() {
        return API.delete(`/api/knowledge/summary`);
      }
    },
    chats: {
      stream() {
        return API.get('/api/stream');
      },
      async list(filters) {
        let qs = "";
        if (filters) {
            const params = Object.entries(filters)
                .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
                .join("&");
            qs = `?${params}`;
        }
        const data = await API.get(`/api/chats${qs}`);
        return data;
      },
      async loadChat({ id, file_path }) {
        const data = await API.get(`/api/chats?file_path=${file_path || ''}&id=${id || ''}`);
        return data;
      },
      async exportChat({ id, exportFormat, clipboard }) {
        const path = `/api/chats?export_format=${exportFormat}&id=${id}`
        if (clipboard) {
          const data = await API.get(path);
          return data;
        } else {
          const url = API.connection.prepareUrl(path)
          window.open(url)
        }
      },
      async newChat() {
        return {
          id: new Date().getTime(),
          name: "New chat"
        };
      },
      async message(chat) {
        return API.post('/api/chats?', chat);
      },
      async fromUrl(chat) {
        return API.post('/api/chats/from-url?', chat);
      },
      async subTasks(chat) {
        return API.post('/api/chats/sub-tasks?', chat);
      },
      save(chat) {
        return API.put(`/api/chats?chatonly=0`, chat);
      },
      saveChatInfo(chat) {
        return API.put(`/api/chats?chatonly=1`, chat);
      },
      delete(chat) {
        return API.del(`/api/chats?chat_id=${chat.id}`);
      },
      // Cancel a running message via POST /api/chat/cancel with token_id in body
      cancelMessage(cancellationTokenId) {
        return API.post(`/api/chat/cancel`, { token_id: cancellationTokenId })
      },
      kanban: {
        async load() {
          const kanban = await API.get('/api/kanban');
          return kanban;
        },
        async save(kanban) {
          API.post('/api/kanban', kanban);
        },
        delete(kanban_title) {
          API.delete('/api/kanban?kanban_title=' + kanban_title);
        }
      }
    },
    run: {
      improve(chat) {
        return API.post('/api/run/improve?', chat);
      },
      patch(patch) {
        return API.post('/api/run/improve/patch?', patch).then(({ data }) => data);
      },
      edit(chat) {
        return API.post('/api/run/edit?', chat);
      },
      liveEdit({ chat, html, url, message }) {
        return API.post('/api/run/live-edit?', { chat_name: chat.name, html, url, message });
      },
      changesSummary({ branch, rebuild }) {
        return API.get(`/api/run/changes/summary?branch=${branch}&refresh=${rebuild}`).then(({ data }) => data);
      }
    },
    profiles: {
      list() {
        return API.get('/api/profiles');
      },
      load(name) {
        return API.get(`/api/profiles/${name}`);
      },
      save(profile) {
        return API.post(`/api/profiles`, profile);
      },
      async delete(name) {
        await API.del(`/api/profiles/${name}`);
      },
      tools() {
        return API.get('/api/profiles/tools');
      }
    },
    coder: {
      openFile(file) {
        API.get(`/api/code-server/file/open?file_name=${encodeURIComponent(file)}`);
      }
    },
    images: {
      async uploadFile(file) {
        let formData = new FormData();
        formData.append("file", file);
        const url = await API.post(`/api/images`, formData);
        return window.location.origin + url;
      },
      async upload(formData) {
        return await API.post(`/api/images`, formData);
      }
    },
    data: {
      rawQuery({ filter, limit }) {
        return API.get(`/api//data/query?search_filter=${filter}&limit=${limit}`)
      }
    },
    wiki: {
      read(path) {
        return API.get(`/api/wiki?file_path=${path}`);
      },
      rebuild() {
        return API.get('/api/wiki-engine/rebuild')
      },
      build(settings) {
        const search = Object.keys(settings).map(k => `${k}=${settings[k]}`).join("&")
        return API.get('/api/wiki-engine/build?' + search)
      },
      config() {
        return API.get('/api/wiki-engine/config')
      },
      save(wikiSettings) {
        return API.put('/api/wiki-engine', wikiSettings)
      }
    },
    engine: {
      update() {
        return API.get('/api/update');
      }
    },
    browser: {
      message(chat) {
        return API.post('/api/browser', chat);
      },
    },
    tools: {
      async imageToText(file) {
        const formData = new FormData();
        formData.append("file", file);
        return (await API.post(`/api/image-to-text`, formData)).data;
      }
    },
    async onUserLogin() {
      API.allProjects = []
      API.activeProject = null
      await Promise.all([
        API.screen.getScreenResolution(),
        API.settings.global.read(),
        API.users.list()
      ])
    },
    async setActiveProject({ project_id }) {
      if (project_id !== API.activeProject?.project_id) {
        API.activeProject = API.allProjects?.find(p => p.project_id === project_id)
        await API.settings.read()
      }
      return API
    },
    logs: {
      async read(logName, size) {
        return API.get(`/api/logs/${logName}?log_size=${size}`);
      },
      async list() {
        return API.get('/api/logs');
      }
    },
    files: {
      list(path) {
        return API.get(`/api/files?path=${path}`);
      },
      read(path) {
        return API.get(`/api/files/read?path=${path}`);
      },
      diff({ path, content }) {
        return API.post(`/api/files/diff`, { path, content });
      },
      search(search) {
        return API.get(`/api/files/find?search=${search}`);
      },
      write(source, page_content) {
        return API.post(`/api/files/write?path=${source}`, { page_content, metadata: { source } });
      }
    },
    screen: {
      display: null,
      async setScreenResolution(resolution) {
        await API.post('/api/screen', { resolution });
        return API.screen.getScreenResolution();
      },
      async getScreenResolution() {
        const display = await API.get('/api/screen');
        API.screen.display = display;
        return API.screen.display;
      }
    },
    async restart() {
      await API.post("/api/restart");
      let waitTime = 3;
      return new Promise((ok, ko) => {
        const ix = setInterval(async () => {
          if (--waitTime) {
            try {
              await API.init();
              clearInterval(ix);
              ok();
            } catch { }
          } else {
            clearInterval(ix);
            ko();
          }
        }, 5000);
      });
    },
    get permissions () {
      const permissions = API.activeProject?.permissions || []
      const isAdmin = API.user?.role === 'admin'
      const isProjectAdmin = permissions.includes("admin")
      return {
        isAdmin,
        isProjectAdmin
      }
    }
  };
  API.initConnection()
  return API;
};

export const API = initializeAPI()
```

## 2. Add views state & actions to ui store

```js client/src/store/ui.js
import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'
import { API } from '../api/api'
import moment from 'moment'

export const namespaced = true

export const state = () => ({
  showCoder: false,
  showBrowser: false,
  lastActiveTab: "",
  codxJuniorWidth: 30,
  isMobile: false,
  orientation: 'portrait',
  openedFile: null,
  showLogs: false,
  voiceLanguage: 'en-US',
  voiceLanguages: {
    "en-US": "English",
    "es-SP": "Español"
  },
  openApps: {},
  appDivided: 'horizontal',
  resolution: API.screen.display?.resolution,
  resolutions: API.screen.display?.resolutions,
  monitor: "preview",
  monitors: {
    "preview": "CODX-SCREEN-PREVIEW",
    "shared": "CODX-SCREEN-SHARED"
  },
  colorsMap: {},
  coderProjectCodxPath: null,
  uiReady: false,
  floatingCodxJunior: false,
  notifications: [],
  noVNCSettings: {
    resize: 'remote',
  },
  theme: 'dark',
  activeTab: 'home',
  newProject: false,
  activeApp: null,
  appShowMode: null,
  // Desktop views persisted per project
  views: [],
  // Desktop API reference (set by Desktop component)
  _desktopApi: null
})

export const getters = getterTree(state, {
  isLandscape: state => state.orientation !== 'portrait',
  monitorToken: state => state.monitors[state.monitor],
  isSharedScreen: () => window.location.pathname === '/shared',
  enableFileManger: () => API.globalSettings?.enable_file_manager,
  activeApps: () => Object.values($storex.ui.openApps)
})

export const mutations = mutationTree(state, {
  setActiveTab(state, tab) {
    tab = tab || 'home'
    if (state.activeTab === tab) {
      if (state.activeApp) {
        state.activeTab = null
      }
    } else {
      state.activeTab = tab
    }
    $storex.ui.showApp({
      name: tab,
      component: tab
    })
    $storex.ui.saveState()
  },
  showTab(state, tab) {
    if (tab !== state.activeTab) {
      $storex.ui.setActiveTab(tab)
    }
    if (!state.isMobile) {
      $storex.ui.showApp({
        name: tab,
        component: tab
      })
    }
  },
  closeTab(state) {
    state.activeTab = null
  },
  setCodxJuniorWidth(state, width) {
    state.codxJuniorWidth = width
    $storex.ui.saveState()
  },
  toggleLogs(state) {
    state.showLogs = !state.showLogs
    $storex.ui.showApp({
      name: 'Logs',
      component: 'log-viewer'
    })
  },
  setVoiceLanguage(state, voiceLanguage) {
    state.voiceLanguage = voiceLanguage
    $storex.ui.saveState()
  },
  setAppDivided(state, divided) {
    state.appDivided = divided
    $storex.ui.saveState()
  },
  setMonitor(state, monitor) {
    state.monitor = monitor
    $storex.ui.saveState()
  },
  setColorsMap(state, colorsMap) {
    state.colorsMap = colorsMap
    $storex.ui.saveState()
  },
  coderOpenPath(state, project) {
    state.coderProjectCodxPath = project.codx_path
  },
  setUIready(state) {
    $storex.ui.loadState()
    state.uiReady = true
  },
  setFloatinCodxJunior(state, floating) {
    state.floatingCodxJunior = floating
    $storex.ui.saveState()
  },
  toggleFloatinCodxJunior(state) {
    state.floatingCodxJunior = !state.floatingCodxJunior
    $storex.ui.saveState()
  },
  addNotification(state, { text, type }) {
    const existing = state.notifications?.find(n => n.text === text)
    if (existing) {
      existing.ts = moment().format("hh:mm:ss")
      return
    }
    const notif = {
      ts: moment().format("hh:mm:ss"),
      text,
      type
    }
    state.notifications.push(notif)
    setTimeout(() => $storex.ui.removeNotification(notif), 30000)
  },
  removeNotification(state, notification) {
    state.notifications.splice(
      state.notifications.findIndex(n => n === notification), 1)
  },
  setNoVNCSettings(state, settings) {
    state.noVNCSettings = { ...state.noVNCSettings, ...settings }
  },
  setTheme(state, theme) {
    state.theme = theme
  },
  showNewProject(state, show) {
    state.newProject = show
  },
  cloneApp(state, app) {
    $storex.ui.showApp({ ...app, tabId: null })
  },
  showApp(state, app) {
    app.tabId = app.tabId || `${app.key || app.name}-${(new Date().getTime())}`
    app.params = app.params || {}
    state.openApps = {
      ...state.openApps,
      [app.tabId]: app
    }
  },
  // Update params of an existing app without creating a new tab
  updateAppParams(state, { tabId, params }) {
    const app = state.openApps[tabId]
    if (!app) return
    state.openApps = {
      ...state.openApps,
      [tabId]: {
        ...app,
        params: {
          ...app.params,
          ...params
        }
      }
    }
  },
  closeApp(state, app) {
    if (!app) return
    delete state.openApps[app.tabId]
    if (state.activeApp?.tabId === app.tabId) {
      state.activeApp = state.openApps[Object.keys(state.openApps).reverse()[0]]
    }
    if (!Object.keys(state.openApps).length) {
      if (!state.activeTab) {
        $storex.ui.showTab(state.lastActiveTab || 'home')
      }
    }
    $storex.ui.saveState()
  },
  setAppShowMode(state, mode) {
    state.appShowMode = mode
  },
  openChat(state, chat) {
    $storex.ui.showApp({
      name: chat.name,
      component: 'chat',
      params: {
        chat: {
          id: chat.id,
          name: chat.name,
          owner_project_id: chat.owner_project_id
        }
      }
    })
  },
  // Store the dockview API reference from the Desktop component
  setDesktopApi(state, api) {
    state._desktopApi = api
  },
  setViews(state, views) {
    state.views = views || []
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init ({ state }, $storex) {
      $storex.ui.handleResize()
      window.addEventListener('resize', () => $storex.ui.handleResize())
      state.activeApp = "home"
      if (API.user?.theme) {
        state.theme = API.user.theme
      }
      state.coderProjectCodxPath = null
    },
    saveState({ state }) {
      if (!state.uiReady) {
        return
      }
      const data = { 
        ...state, 
        uiReady: false,
        activeApp: null,
        openApps: {},
        _desktopApi: null,
        views: []
      }
      localStorage.setItem('uiState', JSON.stringify(data))
    },
    async loadState({ state }) {
      const savedState = localStorage.getItem('uiState')
      if (savedState) {
        const parsedState = JSON.parse(savedState)
        Object.keys(parsedState)
          .forEach(k => state[k] = parsedState[k])
      }
      const {
        activeProject: project_id,
        activeChat: chatId
      } = state

      if (project_id && project_id !== $storex.projects.activeProject?.project_id) {
        await $storex.projects.setActiveProject({ project_id })
      }
      if (chatId && $storex.projects.activeProject) {
        $storex.projects.setActiveChat({ id: chatId })
      }
      state.activeApp = Object.values(state.openApps)[0]

      $storex.ui.handleResize()
    },
    handleResize({ state }) {
      const width = window.innerWidth
      const height = window.innerHeight
      const isMobile = width <= 1024
      const orientation = width > height ? 'landscape' : 'portrait'
      state.isMobile = isMobile
      state.orientation = orientation  
    },
    loadTask (_, task) {
      $storex.projects.setActiveChat(task)
    },
    async openFile({ state }, file) {
      if (state.isMobile) {
        state.openedFile = file
      } else {
        await API.coder.openFile(file)
      }
      state.showCoder = true
    },
    async openProjectFile({ state }, file) {
      const { project_path } = $storex.projects.activeProject
      if (!file.startsWith(project_path)) {
        if (!file.startsWith("/") && !project_path.endsWith("/")) {
          file = "/" + file
        }
        file = project_path + file
      }
      await API.coder.openFile(file)
      state.showCoder = true
    },
    setScreenResolution(_, resolution) {
      API.screen.setScreenResolution(resolution)
    },
    async readScreenResolutions ({ state }) {
      await API.screen.getScreenResolution()
      state.resolution = API.screen.display?.resolution
      state.resolutions = API.screen.display?.resolutions
    },
    copyTextToClipboard(_, text) {
      const textArea = document.createElement('textarea')
      textArea.value = text
      document.body.appendChild(textArea)
      textArea.focus()
      textArea.select()
      document.execCommand('copy')
      document.body.removeChild(textArea)
      $storex.ui.addNotification({ text: "Text copied" })
    },
    async readClipboardText(_, itemType = "text/plain") {
      const items = await navigator.clipboard.read()
      const getText = async item => {
        const blob = await item.getType(itemType)
        return await blob.text()
      }
      const allTexts = await Promise.all(
                        items.filter(i => i.types.includes(itemType))
                              .map(i => getText(i)))
      return allTexts.reduce((a, b) => a + b, "")
    },
    async shareScreen() {
      const stream = await navigator.mediaDevices.getDisplayMedia({
        preferCurrentTab: true,
      })
      const [track] = stream.getVideoTracks()
    },
    openNewWindowAppPanel(_, app) {
      const { origin } = window.location
      const url = `${origin}${app.path}`
      window.open(url, app.name)
    },

    // --- Views actions ---

    // Load views for the active project from API
    async loadViews({ state }) {
      try {
        const views = await API.views.list()
        state.views = views || []
      } catch (ex) {
        console.error("Error loading views", ex)
        state.views = []
      }
    },

    // Save current desktop layout as a named view
    async saveView({ state }, name) {
      const project_id = $storex.projects.activeProject?.project_id
      if (!project_id) return
      const desktop = state._desktopApi ? state._desktopApi.toJSON() : {}
      const view = {
        name,
        project_id,
        desktop
      }
      await API.views.save(view)
      await $storex.ui.loadViews()
      $storex.ui.addNotification({ text: `View "${name}" saved` })
      return view
    },

    // Load a view into the desktop by restoring dockview layout
    async loadView({ state }, view) {
      if (!state._desktopApi || !view?.desktop) return
      try {
        state._desktopApi.fromJSON(view.desktop)
        $storex.ui.addNotification({ text: `View "${view.name}" loaded` })
      } catch (ex) {
        console.error("Error loading view", ex)
      }
    },

    // Delete a view by name
    async deleteView({ state }, name) {
      await API.views.delete(name)
      await $storex.ui.loadViews()
      $storex.ui.addNotification({ text: `View "${name}" deleted` })
    },

    // Rename an existing view
    async renameView({ state }, { oldName, newName }) {
      await API.views.rename(oldName, newName)
      await $storex.ui.loadViews()
      $storex.ui.addNotification({ text: `View renamed to "${newName}"` })
    }
  },
)
