<script>
export default {
  data() {
    return {
      dialog: {
        show: false,
        title: '',
        placeholder: '',
        confirm: 'Save',
        value: '',
        mode: null,   // 'save' | 'rename'
        target: null  // view being renamed
      }
    }
  },
  computed: {
    views() {
      return this.$storex.ui.views || []
    }
  },
  methods: {
    openSaveDialog() {
      this.dialog = {
        show: true,
        title: 'Save current view',
        placeholder: 'View name...',
        confirm: 'Save',
        value: '',
        mode: 'save',
        target: null
      }
      this.$nextTick(() => this.$refs.dialogInput?.focus())
    },
    openRenameDialog(view) {
      this.dialog = {
        show: true,
        title: 'Rename view',
        placeholder: 'New name...',
        confirm: 'Rename',
        value: view.name,
        mode: 'rename',
        target: view
      }
      this.$nextTick(() => this.$refs.dialogInput?.focus())
    },
    closeDialog() {
      this.dialog.show = false
    },
    async confirmDialog() {
      const { mode, value, target } = this.dialog
      if (!value.trim()) return
      if (mode === 'save') {
        await this.$storex.ui.saveView(value.trim())
      } else if (mode === 'rename') {
        await this.$storex.ui.renameView({ oldName: target.name, newName: value.trim() })
      }
      this.closeDialog()
    },
    async loadView(view) {
      await this.$storex.ui.loadView(view)
    },
    async deleteView(name) {
      await this.$storex.ui.deleteView(name)
    }
  }
}
</script>
